insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_2_v1'
from (values
('128.3.b.1.A',1,'A first grader listens to a classmate''s report. To show active listening, the first grader should:','["look at the speaker and think of a question to ask", "stare out the window", "finish the report for them", "start a side talk"]'::jsonb,0,'Active listeners pay attention and ask relevant questions.','original'),
('128.3.b.1.A',2,'Which question helps clarify what a speaker said?','["Who has my pencil?", "Can you tell me more about that part?", "Is it lunchtime?", "Why are you here?"]'::jsonb,1,'Clarifying questions stay on the speaker''s topic.','original'),
('128.3.b.1.B',2,'The teacher says, Open your book, find page ten, and read the first line. What is the last step?','["close the book", "open your book", "reading the opening line", "find page ten"]'::jsonb,2,'Oral instructions follow a sequence.','original'),
('128.3.b.1.B',2,'Giving oral instructions to a partner means telling the steps:','["in a whisper nobody hears", "in any random order", "only with gestures", "clearly and in order"]'::jsonb,3,'Instructions must be clear and sequenced.','original'),
('128.3.b.1.C',1,'Speaking at an appropriate pace means you talk:','["not too fast and not too slow", "without stopping to breathe", "very slowly with long pauses", "as fast as you can"]'::jsonb,0,'A steady pace helps listeners follow.','original'),
('128.3.b.1.C',2,'During a talk about pets, a student should share:','["a story about another day", "ideas about the topic being discussed", "a joke about lunch", "nothing at all"]'::jsonb,1,'Stay on the topic under discussion.','original'),
('128.3.b.1.D',2,'One agreed-upon rule for group discussions is to:','["speak over others", "leave your seat", "raise your hand or wait for a turn", "change the topic every minute"]'::jsonb,2,'Rules help groups work together.','original'),
('128.3.b.1.D',2,'Working collaboratively with a partner on a project means:','["refusing the rules", "ignoring your partner", "doing it all yourself", "sharing ideas and the work"]'::jsonb,3,'Collaboration follows agreed rules.','original'),
('128.3.b.1.E',2,'When you introduce a new student to a friend, you should:','["say each person''s name politely", "leave without a word", "tell a very long story", "whisper a secret"]'::jsonb,0,'Introductions build social communication.','original'),
('128.3.b.1.E',2,'A first grader tells the class about a weekend trip. This is:','["reading a map", "relating an experience", "spelling a word", "adding a prefix"]'::jsonb,1,'Social communication includes sharing experiences.','original'),
('128.3.b.10.A',2,'An author''s purpose is the reason an author:','["bought the pen", "printed the cover", "wrote the text", "chose the paper"]'::jsonb,2,'Authors write to inform, entertain or persuade.','original'),
('128.3.b.10.A',3,'A book with steps for planting a seed was most likely written to:','["sell a toy", "scare you", "entertain with a joke", "inform"]'::jsonb,3,'A how-to text informs.','original'),
('128.3.b.10.B',3,'Text structure in a story that goes beginning, middle, end is called:','["chronological order", "description only", "comparison", "cause only"]'::jsonb,0,'Chronological order follows time.','original'),
('128.3.b.10.B',3,'An author lists facts about a lion''s mane, paws and tail. The structure used is:','["sequence of steps", "description", "rhyme", "dialogue"]'::jsonb,1,'Description tells about features.','original'),
('128.3.b.10.C',2,'A caption under a photograph tells:','["the price", "who printed it", "what the picture shows", "the page color"]'::jsonb,2,'Captions explain graphics.','original'),
('128.3.b.10.C',3,'Why might an author use bold type for an important word?','["to cut it off", "to hide it", "to make the page heavy", "to help it stand out"]'::jsonb,3,'Print features draw attention.','original'),
('128.3.b.10.D',3,'Which sentence uses words that help you picture the scene?','["The tiny yellow chick hopped through the wet green grass.", "It was a day.", "The grass is there.", "The chick moved."]'::jsonb,0,'Descriptive words create mental pictures.','original'),
('128.3.b.10.D',3,'Sensory words help a reader to:','["count pages", "see, hear or feel what is described", "skip lines", "find the author"]'::jsonb,1,'Imagery helps the reader visualize.','original'),
('128.3.b.10.E',2,'A text that says I walked to school is told in:','["second person", "third person", "first person", "no person"]'::jsonb,2,'First person uses I.','original'),
('128.3.b.10.E',2,'A text that says She walked to school is told in:','["second person", "first person", "fourth person", "third person"]'::jsonb,3,'Third person uses he, she or a name.','original'),
('128.3.b.11.A',1,'Before writing, you can plan a first draft by:','["drawing or brainstorming ideas", "erasing the page", "skipping ideas", "copying a book"]'::jsonb,0,'Planning generates ideas.','original'),
('128.3.b.11.A',2,'Brainstorming means:','["writing the final copy", "listing many ideas without judging them", "fixing spelling only", "reading to the class"]'::jsonb,1,'Brainstorming collects ideas.','original'),
('128.3.b.11.B.i',3,'Organizing a piece of writing with structure means giving it:','["only a title", "a random order", "a beginning, middle and end", "no end"]'::jsonb,2,'Structure organizes ideas.','original'),
('128.3.b.11.B.i',3,'A first grader''s story starts with a beginning, then a middle, then an end. This shows:','["rhyme", "handwriting", "punctuation", "structure"]'::jsonb,3,'Structure arranges the parts.','original'),
('128.3.b.11.B.ii',3,'Which sentence has specific, relevant details about a dog?','["My brown dog fetches the red ball at the park.", "Dogs exist.", "I have a dog.", "The dog is."]'::jsonb,0,'Specific details develop an idea.','original'),
('128.3.b.11.B.ii',3,'Adding details helps readers to:','["read faster", "understand your idea better", "finish sooner", "skip the middle"]'::jsonb,1,'Details develop ideas.','original'),
('128.3.b.11.C',2,'To revise a draft, you can:','["throw it away", "tear the page", "add details in words or pictures", "hide it"]'::jsonb,2,'Revising improves drafts.','original'),
('128.3.b.11.C',2,'After a classmate reads your draft, you can revise it by:','["deleting your name", "ignoring them", "copying their paper", "adding what they wanted to know"]'::jsonb,3,'Revision responds to feedback.','original'),
('128.3.b.11.D.i',3,'Subject-verb agreement means that:','["the verb matches the subject", "the sentence is short", "the words rhyme", "the sentence is a question"]'::jsonb,0,'Verbs agree with subjects in number and person.','original'),
('128.3.b.11.D.ii',3,'Which sentence is in the past tense?','["Hoy como una manzana.", "Ayer comí una manzana.", "Mañana como una manzana.", "Siempre como manzanas."]'::jsonb,1,'Ayer signals the past.','original'),
('128.3.b.11.D.ii',3,'In Mi libro está en la mesa, estar tells:','["how old someone is", "what someone is made of", "where something is", "who someone is by name"]'::jsonb,2,'Estar can tell location.','original'),
('128.3.b.11.D.iii',2,'Which article fits the masculine singular noun perro?','["la", "unas", "las", "el"]'::jsonb,3,'Perro is masculine singular.','original'),
('128.3.b.11.D.iv',2,'Which phrase correctly uses an article and an adjective?','["la flor bonita", "el flor bonita", "los flor bonitas", "la flor bonito"]'::jsonb,0,'Articles and adjectives agree with the noun.','original'),
('128.3.b.11.D.iv',2,'In the phrase el gato negro, the word negro tells:','["when the cat ate", "what the cat looks like", "where the cat is", "who owns the cat"]'::jsonb,1,'Adjectives describe nouns.','original'),
('128.3.b.11.D.ix',3,'Which sentence uses the exclamation marks correctly in Spanish?','["Qué bonito día¡", "Qué bonito día!", "¡Qué bonito día!", "¡Qué bonito día"]'::jsonb,2,'Spanish exclamations open with ¡ and close with !.','original'),
('128.3.b.11.D.ix',3,'Which punctuation mark ends a sentence that tells something?','["a hyphen", "a comma", "a colon", "a period"]'::jsonb,3,'Declarative sentences end with a period.','original'),
('128.3.b.11.D.v',3,'Which word tells when something happens?','["hoy", "rápido", "grande", "cerca"]'::jsonb,0,'Hoy is an adverb of time.','original'),
('128.3.b.11.D.v',3,'Which adverb tells that something happened in the past?','["pronto", "ayer", "mañana", "ahora"]'::jsonb,1,'Ayer means yesterday.','original'),
('128.3.b.11.D.vi',2,'In El gato está sobre la silla, the preposition sobre tells:','["the cat''s age", "the cat''s name", "the cat''s position", "the cat''s color"]'::jsonb,2,'Prepositions show relationships of place.','original'),
('128.3.b.11.D.vii',3,'Which possessive word fits: ___ casa (the house belongs to me)?','["tu", "su", "nuestra", "mi"]'::jsonb,3,'Mi means my.','original'),
('128.3.b.11.D.vii',3,'Use usted when speaking to:','["an adult you respect", "a close friend", "a pet", "yourself"]'::jsonb,0,'Usted is the formal you.','original'),
('128.3.b.11.D.viii',1,'The first word of every sentence is written with:','["only vowels", "an uppercase first letter", "no letters", "a lowercase first letter"]'::jsonb,1,'Capitalization marks the start of a sentence.','original'),
('128.3.b.11.D.x',3,'Which spelling of the word for a male sibling is correct?','["hermanno", "jermano", "hermano", "ermano"]'::jsonb,2,'Spanish words with silent h include hermano.','original'),
('128.3.b.11.D.x',3,'Which spelling of the word for the thing that opens a lock is correct?','["jave", "yave", "lyave", "llave"]'::jsonb,3,'The digraph ll is used in llave.','original'),
('128.3.b.11.E',2,'When you publish your writing, you:','["make a final copy to share", "forget it", "rip it up", "hide it away"]'::jsonb,0,'Publishing shares writing with readers.','original'),
('128.3.b.11.E',2,'Sharing a published story with the class can be done by:','["locking it up", "reading it aloud or displaying it", "keeping it secret", "throwing it out"]'::jsonb,1,'Publishing includes sharing.','original'),
('128.3.b.12.A',2,'A poem is an example of:','["a grocery list", "a bus schedule", "a literary text", "a recipe"]'::jsonb,2,'Poetry is literary.','original'),
('128.3.b.12.A',2,'A personal narrative tells:','["a list of numbers", "steps for baking", "facts about stars", "about something that happened to you"]'::jsonb,3,'Personal narratives are about your own life.','original'),
('128.3.b.12.B',3,'A procedural text explains:','["how to do something step by step", "a joke", "a made-up story", "a poem about rain"]'::jsonb,0,'Procedural texts give steps.','original'),
('128.3.b.12.B',3,'Which sentence could begin a procedural text?','["Once upon a time there was a queen.", "First, wash your hands with soap.", "I feel happy today.", "The moon is round."]'::jsonb,1,'Procedures use sequence words and commands.','original'),
('128.3.b.12.C',2,'A thank you note is an example of:','["a recipe", "a dictionary entry", "correspondence", "a nursery rhyme"]'::jsonb,2,'Letters and notes are correspondence.','original'),
('128.3.b.12.C',2,'A thank you note often begins with:','["a lunch order", "a map", "a math problem", "a greeting such as Querida abuela"]'::jsonb,3,'Notes begin with a greeting.','original'),
('128.3.b.13.A',2,'With an adult, a good question to research is:','["How do butterflies grow?", "Blue.", "Yes.", "Butterflies."]'::jsonb,0,'Good questions are open and about a topic.','original'),
('128.3.b.13.A',2,'Formal inquiry begins with:','["a rhyme", "a question", "a title page", "an answer key"]'::jsonb,1,'Inquiry starts with questions.','original'),
('128.3.b.13.B',3,'A research plan with an adult might include:','["a vacation schedule", "only the final answer", "what questions to ask and where to look", "a grocery list"]'::jsonb,2,'Plans list steps and resources.','original'),
('128.3.b.13.B',3,'Following a research plan means:','["ignoring the question", "skipping every step", "guessing the answer", "doing the planned steps in order"]'::jsonb,3,'Plans guide the work.','original'),
('128.3.b.13.C',3,'A relevant source for a report on whales is:','["a book about ocean animals", "a phone book", "a cookbook", "a coloring page of cars"]'::jsonb,0,'Relevant sources match the topic.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_2_v1'
from (values
('128.3.b.13.C',3,'Gathering information means:','["skipping the sources", "finding facts from sources that answer your questions", "copying the whole book", "guessing"]'::jsonb,1,'Information comes from sources.','original'),
('128.3.b.13.D',3,'You show understanding of gathered information when you:','["read only the title", "hide the notes", "explain facts in your own words", "copy the page word for word"]'::jsonb,2,'Explaining shows understanding.','original'),
('128.3.b.13.D',3,'Which shows you understand a fact about owls?','["Night.", "Hunt.", "Owls.", "Owls hunt at night."]'::jsonb,3,'A full statement shows understanding.','original'),
('128.3.b.13.E',2,'After finishing research, you may present results by:','["writing, speaking or a poster", "burying them", "forgetting them", "hiding them"]'::jsonb,0,'Delivery can be written, oral or multimodal.','original'),
('128.3.b.13.E',2,'A poster with words and pictures is an example of:','["a punctuation mark", "a multimodal presentation", "a spelling test", "a dictionary"]'::jsonb,1,'Multimodal combines modes.','original'),
('128.3.b.2.A.i',1,'Which list is a series of rhyming words?','["luna, casa, pan", "pato, mesa, sol", "pato, gato, rato", "gato, flor, mano"]'::jsonb,2,'Rhyming words share ending sounds.','original'),
('128.3.b.2.A.i',1,'Say another word in the series: sal, mal, ___. Which fits?','["sol", "pan", "luz", "tal"]'::jsonb,3,'Tal rhymes with sal and mal.','original'),
('128.3.b.2.A.ii',2,'Which group of words begins with the same syllable?','["cama, casa, cara", "tren, pie, mano", "perro, sol, luz", "uva, ojo, mes"]'::jsonb,0,'All three begin with ca.','original'),
('128.3.b.2.A.ii',2,'Alliteration is when several words in a row:','["have no vowels", "begin with the same sound", "are very long", "end with silence"]'::jsonb,1,'Alliteration repeats beginning sounds.','original'),
('128.3.b.2.A.iii',3,'Say the word cama. Now change the first syllable to sa. What is the new word?','["mama", "casa", "sama", "cama"]'::jsonb,2,'Replacing the first syllable creates a new word.','original'),
('128.3.b.2.A.iii',3,'If you take the syllable lo away from pelota, what word is left?','["lota", "pelo", "pota", "peta"]'::jsonb,3,'Pe-lo-ta without lo is pe-ta.','original'),
('128.3.b.2.A.iv',1,'How many syllables are in the word zapato?','["3", "2", "4", "5"]'::jsonb,0,'Za-pa-to has three syllables.','original'),
('128.3.b.2.A.iv',1,'Segment the word ventana into syllables. How many parts?','["2", "3", "4", "5"]'::jsonb,1,'Ven-ta-na has three syllables.','original'),
('128.3.b.2.A.v',3,'Blend the syllables blan and co. What word is it?','["blando", "claro", "blanco", "bravo"]'::jsonb,2,'Blan plus co forms blanco.','original'),
('128.3.b.2.A.v',3,'Blend gra, ci and as. What word do you hear?','["gratis", "grasas", "grande", "gracias"]'::jsonb,3,'Gra-ci-as is gracias.','original'),
('128.3.b.2.A.vi',3,'How many syllables are in the word brazo?','["2", "4", "1", "3"]'::jsonb,0,'Bra-zo has two syllables.','original'),
('128.3.b.2.A.vi',3,'How many syllables are in the word plato?','["4", "2", "1", "3"]'::jsonb,1,'Pla-to has two syllables with the blend pla.','original'),
('128.3.b.2.A.vii',3,'Move the syllables of sapo so they say the first part last. What do you get?','["paso", "soap", "posa", "sapo"]'::jsonb,2,'Reversing sa and po gives po-sa.','original'),
('128.3.b.2.A.vii',3,'Switch the two syllables of mesa. What do you get?','["masa", "sema", "mesa", "same"]'::jsonb,3,'Me-sa becomes sa-me.','original'),
('128.3.b.2.B.i',1,'Which letter matches the first sound in the word perro?','["p", "b", "d", "t"]'::jsonb,0,'Perro begins with p.','original'),
('128.3.b.2.B.i',1,'Match the sound m to a letter. Which word starts with it?','["pano", "mano", "lano", "nano"]'::jsonb,1,'M is the first letter of mano.','original'),
('128.3.b.2.B.ii',3,'Which word has a sílaba trabada (a consonant blend) like bra?','["casa", "mesa", "libro", "luna"]'::jsonb,2,'Libro contains the blend br.','original'),
('128.3.b.2.B.ii',3,'Which word has the blend gl?','["gasa", "gato", "gema", "globo"]'::jsonb,3,'Globo starts with gl.','original'),
('128.3.b.2.B.iii',3,'In the word que-so, the letter u is:','["silent", "sounded like b", "sounded like n", "sounded like oo"]'::jsonb,0,'In que the u is silent.','original'),
('128.3.b.2.B.iii',3,'Which syllable has a u that is pronounced?','["gue", "güe", "que", "gui"]'::jsonb,1,'The diaeresis shows the u is sounded.','original'),
('128.3.b.2.B.iv',3,'Which word has the diphthong au?','["luna", "mesa", "pausa", "casa"]'::jsonb,2,'Au is two vowels in one syllable.','original'),
('128.3.b.2.B.iv',3,'Which word has the diphthong ai?','["lana", "vaso", "bola", "baile"]'::jsonb,3,'Baile has the ai diphthong.','original'),
('128.3.b.2.B.v',3,'The contraction al is made from:','["a and el", "en and el", "de and el", "por and el"]'::jsonb,0,'A + el = al.','original'),
('128.3.b.2.B.v',3,'The contraction del is made from:','["con and el", "de and el", "en and el", "a and el"]'::jsonb,1,'De + el = del.','original'),
('128.3.b.2.B.vi',3,'How many syllables are in the word mariposa?','["5", "2", "4", "3"]'::jsonb,2,'Ma-ri-po-sa has four syllables.','original'),
('128.3.b.2.B.vi',3,'Which word has exactly three syllables?','["sol", "luz", "pan", "plátano"]'::jsonb,3,'Plá-ta-no has three syllables.','original'),
('128.3.b.2.B.vii',3,'Join the words lava and platos. Which compound word do you make?','["lavaplatos", "lavabo", "platolava", "lavaplato"]'::jsonb,0,'Lava plus platos forms lavaplatos.','original'),
('128.3.b.2.B.viii',3,'The prefix in the word deshacer is:','["-er", "des-", "hac-", "-cer"]'::jsonb,1,'Des- is a prefix that reverses meaning.','original'),
('128.3.b.2.B.viii',3,'The suffix in the word panadero is:','["-a", "pan-", "-ero", "-ad"]'::jsonb,2,'The ending -ero names a worker.','original'),
('128.3.b.2.C.i',2,'Which letter spells the first sound of the word tomate?','["p", "d", "c", "t"]'::jsonb,3,'Tomate begins with t.','original'),
('128.3.b.2.C.i',2,'Which letters spell the last syllable sound in pelota?','["ta", "pa", "ca", "da"]'::jsonb,0,'Pe-lo-ta ends with ta.','original'),
('128.3.b.2.C.ii',3,'Which word has a CCV syllable like bra?','["loma", "brazo", "mano", "casa"]'::jsonb,1,'Br plus a is CCV.','original'),
('128.3.b.2.C.ii',3,'The pattern CVCV is shown by the word:','["sol", "tren", "mesa", "brazo"]'::jsonb,2,'Me-sa is CV plus CV.','original'),
('128.3.b.2.C.iii',3,'Which word is spelled with the digraph rr?','["pezo", "pelo", "pero", "perro"]'::jsonb,3,'Perro is spelled with double r for a trilled sound.','original'),
('128.3.b.2.C.iii',3,'Which word is spelled correctly with a silent h?','["huevo", "juevo", "uevo", "guevo"]'::jsonb,0,'Huevo begins with a silent h.','original'),
('128.3.b.2.C.iv',3,'Spell the word for cheese correctly:','["keso", "queso", "kueso", "cueso"]'::jsonb,1,'Queso uses que.','original'),
('128.3.b.2.C.iv',3,'Which word has gui spelled correctly?','["jitarra", "gitarra", "guitarra", "gitara"]'::jsonb,2,'Gui keeps the g hard before i.','original'),
('128.3.b.2.C.v',3,'Which is the correct way to write a contraction of a plus el?','["el", "a el", "la", "al"]'::jsonb,3,'A + el is spelled al.','original'),
('128.3.b.2.C.v',3,'Which phrase is spelled correctly?','["la casa del perro", "la casa dell perro", "la casa de el perro", "la casa dil perro"]'::jsonb,0,'De + el is spelled del.','original'),
('128.3.b.2.C.vi',3,'Which word has the diphthong ie spelled correctly?','["queero", "quiero", "quero", "kiero"]'::jsonb,1,'Quiero has the ie diphthong.','original'),
('128.3.b.2.C.vii',3,'Which word shows a prefix?','["mar", "arma", "desarmar", "armar"]'::jsonb,2,'Des- is a prefix.','original'),
('128.3.b.2.C.vii',3,'Which word is spelled correctly with the suffix -ero?','["zapatera", "zapatro", "zapatoro", "zapatero"]'::jsonb,3,'The suffix -ero names a worker.','original'),
('128.3.b.2.D',2,'A table of contents helps you find:','["where each part of a book begins", "the author''s age", "the printing house", "the price"]'::jsonb,0,'The table of contents lists parts and pages.','original'),
('128.3.b.2.D',2,'The glossary of a book gives:','["the printing date", "word meanings", "the author''s picture", "page numbers of chapters"]'::jsonb,1,'A glossary defines key words.','original'),
('128.3.b.2.E',2,'A dictionary uses guide words to help you:','["count the pages", "know the price", "find a word on a page", "see the author"]'::jsonb,2,'Guide words show the first and last word on a page.','original'),
('128.3.b.2.F',2,'Good printing leaves space:','["inside letters", "between pages only", "outside the book", "between words"]'::jsonb,3,'Spacing helps others read your writing.','original'),
('128.3.b.2.F',2,'Legible printing means:','["others can read your writing easily", "it is very tiny", "only you can read it", "it has no letters"]'::jsonb,0,'Legible writing is clear.','original'),
('128.3.b.3.A',2,'A digital resource such as an online dictionary can help you:','["draw a picture", "find a word and its meaning", "take a nap", "play a game"]'::jsonb,1,'Resources help find words.','original'),
('128.3.b.3.A',2,'If you do not know a word, you can look in:','["a ruler", "a calendar", "a picture dictionary", "a phone book"]'::jsonb,2,'Dictionaries define words.','original'),
('128.3.b.3.B',3,'An illustration in a story can help you learn:','["the weight of the book", "the page count", "the printing year", "what a new word means"]'::jsonb,3,'Illustrations clarify meaning.','original'),
('128.3.b.3.B',3,'If a text has an unknown word, you can read the sentences around it for:','["clues", "titles", "rhymes", "page numbers"]'::jsonb,0,'Context supplies clues.','original'),
('128.3.b.3.C',3,'The ending -or in the word jugador names:','["a size", "a person who does something", "a color", "a place"]'::jsonb,1,'The suffix -or can name a doer.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_2_v1'
from (values
('128.3.b.3.C',3,'The ending -s added to libro makes:','["one big book", "no books", "more than one", "less than one"]'::jsonb,2,'S makes a noun plural.','original'),
('128.3.b.3.D',2,'Which word names a category?','["roja", "dulce", "manzana", "fruta"]'::jsonb,3,'Fruta is a category that includes manzanas.','original'),
('128.3.b.4',2,'Listening and speaking help you to:','["learn new vocabulary and ideas", "avoid classmates", "forget lessons", "lose words"]'::jsonb,0,'Language skills develop together.','original'),
('128.3.b.4',2,'Reading and writing are skills that:','["replace speaking", "support each other", "stop learning", "never connect"]'::jsonb,1,'They develop together.','original'),
('128.3.b.5',2,'Foundational language skills grow when students:','["only copy words", "never read", "use listening, speaking, reading and writing together", "avoid talking"]'::jsonb,2,'Language skills are developed together.','original'),
('128.3.b.5',2,'A student reads a book, discusses it and writes about it. This builds:','["only math", "only handwriting", "no skills", "several language skills at once"]'::jsonb,3,'Integrated practice builds language.','original'),
('128.3.b.6.A',2,'Setting a purpose for reading means deciding:','["why you are going to read", "how long the book is", "what color it is", "who printed it"]'::jsonb,0,'A purpose guides reading.','original'),
('128.3.b.6.A',2,'A purpose for reading a book about sharks might be:','["to hide it", "to learn how sharks live", "to guess the author", "to count pages"]'::jsonb,1,'Informational reading has a learning purpose.','original'),
('128.3.b.6.B',2,'Which question is good to ask before reading a book about trains?','["Where is my lunch?", "What day is it?", "What might I learn about trains?", "Who is next?"]'::jsonb,2,'Questions before reading prepare you.','original'),
('128.3.b.6.B',3,'Asking questions during reading helps you:','["forget the plot", "finish sooner", "skip pages", "check and deepen understanding"]'::jsonb,3,'Questions build comprehension.','original'),
('128.3.b.6.C',3,'A prediction can be confirmed or corrected after:','["you read more of the text", "you close the book", "you skip the middle", "you guess again"]'::jsonb,0,'Check predictions against the text.','original'),
('128.3.b.6.C',3,'Looking at a title and pictures to guess what will happen is:','["spelling", "making a prediction", "punctuating", "rhyming"]'::jsonb,1,'Text features support predictions.','original'),
('128.3.b.6.D',2,'Making pictures in your mind as you read is called:','["reading backward", "skipping words", "creating mental images", "counting letters"]'::jsonb,2,'Mental images deepen understanding.','original'),
('128.3.b.6.D',2,'The text says a red balloon floated above a green hill. You can picture:','["a snowy mountain", "a crowded bus", "a cave", "a balloon over a hill"]'::jsonb,3,'Words help readers visualize.','original'),
('128.3.b.6.E',3,'When a story reminds you of another book you read, you are making:','["a text-to-text connection", "a title", "a new rhyme", "a spelling error"]'::jsonb,0,'Connections link texts.','original'),
('128.3.b.6.E',3,'A story about moving houses reminds you of your own move. This is a:','["map", "personal connection", "rhyme", "caption"]'::jsonb,1,'Connections tie to experience.','original'),
('128.3.b.6.F',3,'A boy slams the door and stomps. What can you infer?','["he is hungry", "he is sleepy", "he is angry", "he is cold"]'::jsonb,2,'Actions give evidence for inferences.','original'),
('128.3.b.6.F',3,'An inference uses clues from the text and:','["only the title", "only the page numbers", "only the cover", "what you already know"]'::jsonb,3,'Inferences combine evidence and background.','original'),
('128.3.b.6.G',3,'Evaluating details to find what is most important helps you:','["find the main idea", "count the words", "spell better", "find the page"]'::jsonb,0,'Important details point to the main idea.','original'),
('128.3.b.6.G',3,'Which detail is most important in a story about a girl who finds a lost cat?','["she wears a hat", "she finds a lost cat", "the sky is blue", "the street is long"]'::jsonb,1,'The central event is key.','original'),
('128.3.b.6.H',3,'Combining information from a text to make a new idea is called:','["rhyming", "copying", "synthesizing", "alphabetizing"]'::jsonb,2,'Synthesis creates new understanding.','original'),
('128.3.b.6.H',3,'After reading three facts about bats, you summarize them in one idea. This is:','["a title", "a rhyme", "a caption", "synthesis"]'::jsonb,3,'Synthesis pulls ideas together.','original'),
('128.3.b.6.I',3,'If you do not understand a paragraph, a helpful strategy is to:','["re-read it slowly", "skip the book", "close your eyes", "guess the end"]'::jsonb,0,'Re-reading is a repair strategy.','original'),
('128.3.b.6.I',3,'Monitoring your comprehension means:','["skipping the hard parts", "noticing when you do not understand", "counting the words", "listing the characters only"]'::jsonb,1,'Monitoring includes checking and adjusting.','original'),
('128.3.b.7.A',2,'A personal connection to a source is how it:','["is shelved", "rhymes", "relates to your own life", "is printed"]'::jsonb,2,'Describe personal connections to sources.','original'),
('128.3.b.7.A',2,'After reading about a school day, you tell how your school day is the same. This is:','["a rhyme", "a punctuation mark", "a map", "a personal connection"]'::jsonb,3,'Responding with connections.','original'),
('128.3.b.7.B',3,'A brief comment about a story might say:','["I liked the part where the dog finds the bone.", "Page ten.", "The.", "Bone."]'::jsonb,0,'Comments tell your thoughts about the text.','original'),
('128.3.b.7.B',3,'Writing brief comments about a text helps you to:','["hide your ideas", "share your thinking", "lose the place", "erase the book"]'::jsonb,1,'Written comments are responses.','original'),
('128.3.b.7.C',3,'Text evidence for a response is:','["a guess without proof", "a drawing of a pet", "a detail from the text that supports it", "a favorite food"]'::jsonb,2,'Evidence supports a response.','original'),
('128.3.b.7.C',3,'You say the girl was brave because she walked into the dark cave alone. The words about the cave are:','["a title", "a caption", "a rhyme", "text evidence"]'::jsonb,3,'Evidence from the text supports your point.','original'),
('128.3.b.7.D',2,'To retell a story and keep its meaning, you tell:','["the main events in order", "only the ending", "only your favorite word", "a different story"]'::jsonb,0,'Retelling maintains meaning.','original'),
('128.3.b.7.D',2,'A good retelling does not:','["follow story order", "change the meaning of the story", "include the main events", "keep the characters"]'::jsonb,1,'A retelling should keep the original meaning.','original'),
('128.3.b.7.E',2,'Interacting with a source in a meaningful way includes:','["ignoring it", "tearing it", "drawing or writing about it", "leaving it closed"]'::jsonb,2,'Meaningful interaction responds to text.','original'),
('128.3.b.7.E',2,'After reading a nonfiction book, you might:','["close your ears", "tear a page", "hide the book", "draw and label a diagram"]'::jsonb,3,'Illustrating and writing are responses.','original'),
('128.3.b.7.F',3,'Responding with newly acquired vocabulary means:','["using words you just learned in your answer", "repeating only easy words", "avoiding hard words", "staying quiet"]'::jsonb,0,'New vocabulary shows learning.','original'),
('128.3.b.7.F',3,'The teacher teaches the word enorme. Which response uses it?','["Enorme.", "El elefante es enorme.", "Un elefante pequeño.", "El elefante."]'::jsonb,1,'The new word is used meaningfully.','original'),
('128.3.b.8.A',3,'A story shows a boy telling the truth even when it is hard. A possible theme is:','["speed", "food", "honesty", "weather"]'::jsonb,2,'Text evidence points to the theme.','original'),
('128.3.b.8.B',2,'Describing a main character includes telling:','["the printing date", "the page count", "the author''s age", "why the character acts a certain way"]'::jsonb,3,'Characters have reasons for their actions.','original'),
('128.3.b.8.B',3,'A girl shares her lunch because her friend forgot his. Her reason is:','["she wants to help her friend", "she is bored", "she is hungry", "she dislikes lunch"]'::jsonb,0,'Actions have motives.','original'),
('128.3.b.8.C',3,'The problem of a story is also called:','["the setting", "the conflict", "the title", "the illustration"]'::jsonb,1,'The problem is part of plot.','original'),
('128.3.b.8.C',3,'The main events, the problem and the resolution make up the:','["title", "theme", "plot", "setting"]'::jsonb,2,'Plot includes events, problem and resolution.','original'),
('128.3.b.8.D',2,'A story takes place in a snowy village at night. This describes:','["the plot", "the author", "the theme", "the setting"]'::jsonb,3,'Snowy village at night is the place and time.','original'),
('128.3.b.9.A',2,'A well-known characteristic of a fairy tale is:','["magical events", "a table of contents", "a glossary", "a map key"]'::jsonb,0,'Fairy tales have magic.','original'),
('128.3.b.9.A',2,'A fable is a short story that teaches:','["a phone number", "a lesson", "a spelling list", "a recipe"]'::jsonb,1,'Fables end with a moral.','original'),
('128.3.b.9.B',2,'Repetition in a poem means:','["it has no title", "no words appear", "words or lines repeat", "every word is different"]'::jsonb,2,'Repetition is a poetic device.','original'),
('128.3.b.9.B',2,'When several words in a line begin with the same sound, the poem uses:','["rhythm only", "prose", "a title", "alliteration"]'::jsonb,3,'Alliteration repeats initial sounds.','original'),
('128.3.b.9.C',2,'In a play, the characters speak in:','["dialogue", "indexes", "glossaries", "captions"]'::jsonb,0,'Drama uses dialogue.','original'),
('128.3.b.9.C',2,'Two elements of a drama are characters and:','["caption", "setting", "glossary", "index"]'::jsonb,1,'Drama has characters and setting.','original'),
('128.3.b.9.D.i',3,'Supporting evidence for a central idea about penguins would be:','["a rhyme", "a joke", "facts about how penguins live", "a color"]'::jsonb,2,'Evidence supports the main idea.','original'),
('128.3.b.9.D.ii',2,'A heading in an informational text tells:','["the price", "the author''s age", "who printed it", "what a section is about"]'::jsonb,3,'Headings organize text.','original'),
('128.3.b.9.D.ii',2,'A map or diagram can help you:','["find information quickly", "skip the title", "lose the page", "hide the topic"]'::jsonb,0,'Graphics provide information.','original'),
('128.3.b.9.D.iii',3,'Telling events in time order is called:','["dialogue", "chronological order", "comparison", "description"]'::jsonb,1,'Chronological means by time.','original'),
('128.3.b.9.D.iii',3,'A text that tells how something looks, sounds and feels uses:','["sequence only", "rhyme only", "description", "dialogue only"]'::jsonb,2,'Description is an organizational pattern.','original'),
('128.3.b.9.E',3,'A persuasive text tries to:','["show a map", "only list facts", "tell a rhyme", "convince you to agree with the author"]'::jsonb,3,'Persuasion has an author''s goal.','original'),
('128.3.b.9.E',3,'An author writes, Everyone should recycle to help the planet. The author''s goal is to:','["persuade you to recycle", "explain a game", "tell a joke", "describe a tree"]'::jsonb,0,'Persuasive texts state what the author wants.','original'),
('128.3.b.9.F',2,'A website is an example of:','["a spoken rhyme", "a digital text", "a printed poster only", "a handwritten letter"]'::jsonb,1,'Digital texts appear on devices.','original'),
('128.3.b.9.F',3,'A multimodal text might combine:','["only numbers", "only one letter", "words, images and sound", "only a blank page"]'::jsonb,2,'Multimodal uses several modes.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
